CREATE OR REPLACE FUNCTION public.award_exp(_user_id bigint, _rule_key character varying, _source_type character varying, _source_id bigint, _multiplier numeric DEFAULT 1, _metadata jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(created boolean, awarded integer, exp_after bigint, previous_level integer, new_level integer)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_amount int;
BEGIN
    SELECT CEIL(r.amount * GREATEST(_multiplier, 0))::int INTO v_amount
    FROM profile.exp_rule r
    WHERE r.rule_key = _rule_key AND r.is_active;

    IF v_amount IS NULL OR v_amount <= 0 THEN
        RETURN QUERY
        SELECT false, 0, i.exp, i.exp_level, i.exp_level FROM profile.info i WHERE i.user_id = _user_id;
        RETURN;
    END IF;

    RETURN QUERY SELECT * FROM public.post_exp(_user_id, v_amount, _source_type, _source_id, _rule_key, NULL, NULL, NULL, _metadata);
END;
$function$;
